@pytest.mark.parametrize('name_in,name_out', (
    ('foo', 'foo'),
    ('foo.1', 'foo-1'),
    ('foo.bar.baz', 'foo-bar-baz'),
    ('foo_bar_baz', 'foo_bar_baz'),
    ('foo!bar:baz', 'foo-bar-baz'),
    ('καλημέρα.κόσμε', 'καλημέρα-κόσμε'),
))
def test_dashrepl(name_in, name_out):
    assert dashrepl(name_in) == name_out

@pytest.mark.parametrize('val_in,val_out', (
    ('foo', 'foo'),
    ('foo name.%h', 'foo name.%%h'),
    ('%one two% %three', '%%one two%% %%three'),
    ('foo%%bar', 'foo%%%%bar'),
))
def test_percentescape(val_in, val_out):
    assert percentescape(val_in) == val_out

def test_add_process_updates_printer_width(self):
    self.m.add_process('interesting', 'ruby server.rb')
    assert self.p.width == len('interesting')

def test_add_process_sets_name(self):
    proc = self.m.add_process('foo', 'ruby server.rb')
    assert proc.name == 'foo'

def test_add_process_sets_cmd(self):
    proc = self.m.add_process('foo', 'ruby server.rb')
    assert proc.cmd == 'ruby server.rb'

def test_add_process_sets_colour(self):
    proc = self.m.add_process('foo', 'ruby server.rb')
    assert proc.colour is not None

def test_add_process_sets_quiet(self):
    proc = self.m.add_process('foo', 'ruby server.rb', quiet=True)
    assert proc.quiet

def test_add_process_sets_cwd(self):
    proc = self.m.add_process('foo', 'ruby server.rb', cwd='foo-dir')
    assert proc.cwd == 'foo-dir'

def test_returncode_set_by_first_exiting_process(self):
    self.run_history('returncode')
    assert self.h.manager_returncode == 456

@pytest.mark.parametrize('commands', [
    # Regression test for #173
    [
        ['start', '-f', 'Procfile'],
        ['-f', 'Procfile', 'start'],
    ],
    # Regression tests for #223
    [
        ['start', '--no-prefix'],
        ['--no-prefix', 'start'],
    ],
    [
        ['start', '--no-colour'],
        ['--no-colour', 'start'],
    ],
    [
        ['start', '--no-prefix', '--no-colour'],
        ['--no-colour', 'start', '--no-prefix'],
        ['--no-prefix', 'start', '--no-colour'],
        ['--no-prefix','--no-colour', 'start'],
    ]
])
def test_command_equivalence(commands):
    if len(commands) < 2:
        pytest.fail("Must supply at least two commands")

    reference_args = commands.pop(0)
    reference_result = command.parser.parse_args(reference_args)

    for args in commands:
        result = command.parser.parse_args(args)
        assert result == reference_result

def test_ctor_cmd(self):
    proc = Process('echo 123')
    assert proc.cmd == 'echo 123'

def test_ctor_name(self):
    proc = Process('echo 123', name='foo')
    assert proc.name == 'foo'

def test_ctor_colour(self):
    proc = Process('echo 123', colour='red')
    assert proc.colour == 'red'

def test_ctor_quiet(self):
    proc = Process('echo 123', quiet=True)
    assert proc.quiet

def test_render_uses_app_name_as_filename(self):
    export = Export()
    export.get_template = MagicMock()

    results = export.render([], {'app': 'elephant'})

    assert results[0].name == 'elephant.conf'

@pytest.mark.parametrize('content,processes', [
    [
        # Simple
        """
        web: command
        """,
        {'web': 'command'}
    ],
    [
        # Simple 2
        """
        foo: python foo.py
        bar: python bar.py
        """,
        {'foo': 'python foo.py', 'bar': 'python bar.py'}
    ],
    [
        # No newline at EOF
        """
        web: command""",
        {'web': 'command'}
    ],
    [
        # Comments
        """
        #commented: command
        """,
        {}
    ],
    [
        # Invalid characters
        """
        +foo: command
        """,
        {}
    ],
    [
        # Valid -/_ characters
        """
        -foo_bar: command
        """,
        {'-foo_bar': 'command'}
    ],
    [
        # Shell metacharacters
        """
        web: sh -c "echo $FOOBAR" >/dev/null 2>&1
        """,
        {'web': 'sh -c "echo $FOOBAR" >/dev/null 2>&1'}
    ],
])
def test_parse_procfile(content, processes):
    content = textwrap.dedent(content)
    p = environ.parse_procfile(content)
    assert p.processes == processes

def test_expand_processes_command():
    p = ep(("foo", "some command"))
    assert p[0].cmd == "some command"

def test_expand_processes_port_not_defaulted():
    p = ep(("foo", "some command"))
    assert "PORT" not in p[0].env

def test_expand_processes_port():
    p = ep(("foo", "some command"), port=8000)
    assert p[0].env["PORT"] == "8000"

def test_expand_processes_port_from_env_coerced_to_number():
    p = ep(("foo", "some command"), env={"PORT": "5000"})
    assert p[0].env["PORT"] == "5000"

def test_expand_processes_port_from_env_overrides():
    p = ep(("foo", "some command"), env={"PORT": 5000}, port=8000)
    assert p[0].env["PORT"] == "5000"

def test_expand_processes_quiet():
    p = ep(("foo", "some command"), quiet=["foo", "bar"])
    assert p[0].quiet

def test_has_no_processes_after_init(self):
    p = environ.Procfile()
    assert len(p.processes) == 0

@pytest.mark.parametrize('testenv', [{
    'Procfile': "web: python web.py"
}], indirect=True)
def test_export_supervisord(testenv):
    ret, out, err = testenv.run_honcho([
        'export',
        'supervisord',
        testenv.path('giraffe'),
        '-a', 'neck',
    ])

    expected = testenv.path('giraffe', 'neck.conf')

    assert ret == 0
    assert os.path.exists(expected)

@pytest.mark.parametrize('testenv', [{
    'Procfile': "web: python web.py"
}], indirect=True)
def test_export_upstart(testenv):
    ret, out, err = testenv.run_honcho([
        'export',
        'upstart',
        testenv.path('elephant'),
        '-a', 'trunk',
    ])

    assert ret == 0
    for filename in ('trunk.conf',
                     'trunk-web.conf',
                     'trunk-web-1.conf'):
        expected = testenv.path('elephant', filename)
        assert os.path.exists(expected)

@pytest.mark.parametrize('testenv', [{
    'Procfile': 'foo: {0} test.py'.format(python_bin),
    'test.py': script,
}], indirect=True)
def test_start(testenv):
    ret, out, err = testenv.run_honcho(['start'])

    assert ret == 0
    assert 'elephant' in out
    assert 'error output' in out

@pytest.mark.parametrize('testenv', [{
    '.env': 'ANIMAL=giraffe',
    'Procfile': 'foo: {0} test.py'.format(python_bin),
    'test.py': script,
}], indirect=True)
def test_start_env(testenv):
    ret, out, err = testenv.run_honcho(['start'])

    assert 'giraffe' in out

@pytest.mark.parametrize('testenv', [{
    '.env': 'PROCFILE=Procfile.dev',
    'Procfile': 'foo: {0} test.py'.format(python_bin),
    'Procfile.dev': 'bar: {0} test_dev.py'.format(python_bin),
    'test.py': script,
    'test_dev.py': textwrap.dedent("""
        print("mongoose")
        """)
}], indirect=True)
def test_start_env_procfile(testenv):
    ret, out, err = testenv.run_honcho(['start'])

    assert 'mongoose' in out

@pytest.mark.parametrize('testenv', [{
    'Procfile': 'foo: {0} test.py'.format(python_bin),
    'test.py': 'import sys; sys.exit(42)',
}], indirect=True)
def test_start_returncode(testenv):
    ret, out, err = testenv.run_honcho(['start'])

    assert ret == 42

@pytest.mark.parametrize('testenv', [{
    'Procfile': textwrap.dedent("""
        foo: python web.py
        bar: ruby worker.rb
        baz: node socket.js
    """)
}], indirect=True)
def test_check(testenv):
    ret, out, err = testenv.run_honcho(['check'])

    assert ret == 0
    assert 'Valid procfile detected' in err
    assert 'foo, bar, baz' in err

@pytest.mark.parametrize('testenv', [{
    'Procfile': textwrap.dedent("""
        foo: python web.py
        bar: ruby worker.rb
    """)
}], indirect=True)
def test_main(testenv):
    result = testenv.run(['python', '-m', 'honcho', 'check'], check=True)

    assert 'Valid procfile detected' in result.stderr
    assert 'foo, bar' in result.stderr

@pytest.mark.parametrize('testenv', [{
    'test.py': script
}], indirect=True)
def test_run(testenv):
    ret, out, err = testenv.run_honcho(['run', python_bin, 'test.py'])

    assert ret == 0
    assert out == 'elephant\n'
    assert 'error output\n' in err

@pytest.mark.parametrize('testenv', [{
    '.env': 'ANIMAL=giraffe',
    'test.py': script,
}], indirect=True)
def test_run_env(testenv):
    ret, out, err = testenv.run_honcho(['run', python_bin, 'test.py'])

    assert ret == 0
    assert out == 'giraffe\n'

@pytest.mark.parametrize('testenv', [{
    '.env.x': 'ANIMAL=giraffe',
    'test.py': script,
}], indirect=True)
def test_run_args_before_command(testenv):
    # Regression test for #122 -- ensure that common args can be given
    # before the subcommand.
    ret, out, err = testenv.run_honcho(['-e', '.env.x',
                                        'run', python_bin, 'test.py'])

    assert ret == 0
    assert out == 'giraffe\n'

@pytest.mark.parametrize('testenv', [{
    'test.py': script
}], indirect=True)
def test_run_options_positionals_separator(testenv):
    # Regression test for #159 -- ensure that honcho handles the '--'
    # options/positionals separator correctly.
    ret, out, err = testenv.run_honcho(['run', '--', python_bin, 'test.py'])

    assert ret == 0
    assert out == 'elephant\n'
